class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        def longest_pal_sub(x: str) -> int:
            best = 0
            n = len(x)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    c = x[i:j]
                    if len(c) > best and c == c[::-1]:
                        best = len(c)
            return best

        best = max(longest_pal_sub(s), longest_pal_sub(t))

        n, m = len(s), len(t)
        subs_s = [s[i:j] for i in range(n) for j in range(i + 1, n + 1)]
        subs_t = [t[i:j] for i in range(m) for j in range(i + 1, m + 1)]

        for a in subs_s:
            la = len(a)
            for b in subs_t:
                lc = la + len(b)
                if lc > best:
                    c = a + b
                    if c == c[::-1]:
                        best = lc
        return best
